CREATE TABLE IF NOT EXISTS room_automation_devices(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,room_number TEXT NOT NULL,device_family TEXT NOT NULL,provider TEXT NOT NULL,external_device_id TEXT,status TEXT NOT NULL DEFAULT 'DISCOVERED',last_seen_at TEXT,capabilities_json TEXT NOT NULL DEFAULT '[]',UNIQUE(organization_id,property_id,provider,external_device_id));
CREATE TABLE IF NOT EXISTS room_energy_policies(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,name TEXT NOT NULL,trigger_type TEXT NOT NULL,conditions_json TEXT NOT NULL,proposed_actions_json TEXT NOT NULL,approval_mode TEXT NOT NULL DEFAULT 'REQUIRED',enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS room_energy_action_proposals(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,room_number TEXT NOT NULL,policy_id TEXT,trigger_evidence_json TEXT NOT NULL,action_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PROPOSED',approved_by TEXT,executed_at TEXT,rollback_json TEXT,created_at TEXT NOT NULL,FOREIGN KEY(policy_id) REFERENCES room_energy_policies(id));
CREATE TABLE IF NOT EXISTS guest_tv_message_drafts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,room_number TEXT NOT NULL,reservation_reference TEXT,message_type TEXT NOT NULL,message_text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',scheduled_at TEXT,expires_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS energy_savings_evidence(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,room_number TEXT,period_start TEXT NOT NULL,period_end TEXT NOT NULL,baseline_kwh REAL,actual_kwh REAL,estimated_savings_kwh REAL,estimated_savings_cents INTEGER,evidence_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
